// Simple plain-text email. Input: teacher_email, sheet_url, day, topic, feedback_summary, changes[]
const j = $json;
const changes = (j.changes || []).slice(0, 4).map(c => '- ' + c).join('\n');
const subject = 'Your maths plan is updated (Day ' + j.day + (j.topic ? ', ' + j.topic : '') + ')';
const body = [
  'Hi,',
  '',
  'Thank you for telling us how Day ' + j.day + ' went.',
  '',
  'What you told us: ' + j.feedback_summary,
  '',
  'What we changed:',
  changes || '- Nothing needed to change.',
  '',
  'Your full plan is here: ' + j.sheet_url,
  '',
  'Thanks,',
  'Your maths helper',
].join('\n');
const raw = [
  'To: ' + j.teacher_email,
  'Subject: =?UTF-8?B?' + Buffer.from(subject).toString('base64') + '?=',
  'Content-Type: text/plain; charset=UTF-8',
  '',
  body,
].join('\r\n');
return [{ json: { subject, body, raw: Buffer.from(raw).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '') } }];
